mapper.select:
SELECT V. ID, V.VEHICLE_PLATE, V.AREA_NAME, V.SNAP_PHOTO_ID, V.EVENT_TYPE, V.SNAP_TIME, V.DRIVER_NAME, V.DRIVER_PHONE, V.AUTHORITY, V.LET_PASS, V.CREATE_TIME, SV.COMPANY,P.PARK_NAME FROM SMT_SNAP_VEHICLE V LEFT JOIN SMT_VISITOR SV ON V.DRIVER_ID = SV. ID INNER JOIN SMT_PARK P ON V.PARK_ID=P.ID
V.DRIVER_TYPE !=1
AND V.VEHICLE_PLATE LIKE CONCAT(CONCAT('%',#{query.vehiclePlate}),'%')
AND V.AREA_ID=#{query.areaId}
AND V.EVENT_TYPE=#{query.eventType}
AND V.DRIVER_NAME LIKE CONCAT(CONCAT('%',#{query.driverName}),'%')
AND V.DRIVER_PHONE LIKE CONCAT(CONCAT('%',#{query.driverPhone}),'%')
AND V.SNAP_TIME >= TO_DATE(#{query.startTime}, 'yyyy-mm-dd hh24:mi:ss')
AND V.SNAP_TIME <= TO_DATE(#{query.endTime}, 'yyyy-mm-dd hh24:mi:ss')
AND V.PARK_ID=#{query.parkId}
and V.PARK_ID in
#{item}
ORDER BY V.SNAP_TIME DESC

SELECT V. ID, SAV.PLATE, V.AREA_NAME, V.SNAP_PHOTO_ID, V.EVENT_TYPE, V.SNAP_TIME, V.DRIVER_NAME, V.DRIVER_PHONE, V.AUTHORITY, V.LET_PASS, V.CREATE_TIME, SV.COMPANY,P.PARK_NAME FROM SMT_SNAP_VEHICLE V LEFT JOIN SMT_ADMITTANCE_VEHICLE SAV ON V.DRIVER_ID = SAV.ID LEFT JOIN SMT_VISITOR SV ON SAV.VISITOR_ID = SV.ID INNER JOIN SMT_PARK P ON V.PARK_ID=P.ID
V.DRIVER_TYPE !=1
AND V.VEHICLE_PLATE LIKE CONCAT(CONCAT('%',#{query.vehiclePlate}),'%')
AND V.AREA_ID=#{query.areaId}
AND V.EVENT_TYPE=#{query.eventType}
AND V.DRIVER_NAME LIKE CONCAT(CONCAT('%',#{query.driverName}),'%')
AND V.DRIVER_PHONE LIKE CONCAT(CONCAT('%',#{query.driverPhone}),'%')
AND V.SNAP_TIME >= TO_DATE(#{query.startTime}, 'yyyy-mm-dd hh24:mi:ss')
AND V.SNAP_TIME <= TO_DATE(#{query.endTime}, 'yyyy-mm-dd hh24:mi:ss')
AND V.PARK_ID=#{query.parkId}
and V.PARK_ID in
#{item}
ORDER BY V.SNAP_TIME DESC

SELECT V. ID, V.VEHICLE_PLATE, V.AREA_NAME, V.SNAP_PHOTO_ID, V.EVENT_TYPE, V.SNAP_TIME, V.DRIVER_NAME, V.DRIVER_PHONE, V.AUTHORITY, V.LET_PASS, P.PARK_NAME, V.CREATE_TIME, ST.COMP_NAME FROM SMT_SNAP_VEHICLE V LEFT JOIN SMT_STAFF ST ON V.DRIVER_ID = ST. ID INNER JOIN SMT_PARK P ON V.PARK_ID=P.ID
V.DRIVER_TYPE = 1
AND V.VEHICLE_PLATE LIKE CONCAT(CONCAT('%',#{query.vehiclePlate}),'%')
AND ST.COMP_ID=#{query.compId}
AND ST.DEP_ID=#{query.depId}
AND V.AREA_ID=#{query.areaId}
AND V.EVENT_TYPE=#{query.eventType}
AND V.DRIVER_NAME LIKE CONCAT(CONCAT('%',#{query.driverName}),'%')
AND V.SNAP_TIME >= TO_DATE(#{query.startTime}, 'yyyy-mm-dd hh24:mi:ss')
AND V.SNAP_TIME <= TO_DATE(#{query.endTime}, 'yyyy-mm-dd hh24:mi:ss')
AND V.PARK_ID=#{query.parkId}
and V.PARK_ID in
#{item}
ORDER BY V.SNAP_TIME DESC

SELECT V_SNAP_VEHICLE. ID, V_SNAP_VEHICLE.VEHICLE_PLATE, V_SNAP_VEHICLE.EVENT_TYPE, V_SNAP_VEHICLE.SNAP_TIME, V_SNAP_VEHICLE.DRIVER_NAME, V_SNAP_VEHICLE.DRIVER_PHONE, V_SNAP_VEHICLE.PARK_ID FROM ( SELECT ROW_NUMBER () OVER ( PARTITION BY VEHICLE_PLATE ORDER BY SNAP_TIME DESC ) rn, SMT_SNAP_VEHICLE. ID, SMT_SNAP_VEHICLE.VEHICLE_PLATE, SMT_SNAP_VEHICLE.EVENT_TYPE, SMT_SNAP_VEHICLE.DRIVER_NAME, SMT_SNAP_VEHICLE.DRIVER_PHONE, SMT_SNAP_VEHICLE.SNAP_TIME, SMT_SNAP_VEHICLE.CREATE_TIME, SMT_SNAP_VEHICLE.PARK_ID FROM SMT_SNAP_VEHICLE
AND SMT_SNAP_VEHICLE.PARK_ID = #{query.parkId}
AND SMT_SNAP_VEHICLE.PARK_ID IN
#{tempId}
AND SMT_SNAP_VEHICLE.VEHICLE_PLATE LIKE CONCAT(CONCAT('%',#{query.vehiclePlate}),'%')
AND SMT_SNAP_VEHICLE.DRIVER_NAME LIKE CONCAT(CONCAT('%',#{query.driverName}),'%')
AND SMT_SNAP_VEHICLE.SNAP_TIME >= TO_DATE(#{query.startTime}, 'yyyy-MM-dd')
AND SMT_SNAP_VEHICLE.SNAP_TIME < TO_DATE(#{query.endTime}, 'yyyy-MM-dd') + 1
AND SMT_SNAP_VEHICLE.DEVICE_ID IN( SELECT SMT_DEVICE."ID" FROM SMT_DEVICE WHERE SMT_DEVICE.DEVICE_SUBTYPE = #{query.parkingId} )
) V_SNAP_VEHICLE
AND V_SNAP_VEHICLE.RN = 1
AND V_SNAP_VEHICLE.EVENT_TYPE = #{query.eventType}
ORDER BY V_SNAP_VEHICLE.SNAP_TIME DESC

SELECT V.SNAP_PHOTO_ID, V.DRIVER_ID, V.CREATE_TIME, V.SNAP_TIME FROM SMT_SNAP_VEHICLE V
V.VEHICLE_ASCRIPTION=#{query.vehicleAscription}
AND V.EVENT_TYPE=#{query.eventType}
AND V.SNAP_TIME >= TO_DATE(#{query.startTime}, 'yyyy-mm-dd hh24:mi:ss')
AND V.SNAP_TIME <= TO_DATE(#{query.endTime}, 'yyyy-mm-dd hh24:mi:ss')
ORDER BY V.SNAP_TIME DESC

SELECT * FROM ( select AREA_NAME,SNAP_TIME,VEHICLE_PLATE,EVENT_TYPE from smt_snap_vehicle
where PARK_ID=#{parkId}
ORDER BY SNAP_TIME desc) WHERE ROWNUM <= 4
